function MINIMAL(points, leq):
    P <- deduplicate(points)
    M <- empty list
    for x in P:
        is_minimal <- true
        for y in P with y != x:
            if leq(y, x):            # y <= x, y strictly below x
                is_minimal <- false
                break
        if is_minimal:
            append x to M
    return M                          # M is a finite antichain (WQO)

